// HMZC LTD's official digital stamp — requested directly: "include this
// stamp to all certificate, and invoice, this is supposed to be the
// digital stamp of HMZC." Processed from the original scanned stamp
// (a JPEG with a solid white background) into a transparent PNG —
// pixel alpha set from brightness (near-white -> transparent, dark ink
// -> opaque) — so it can sit directly over a signature and still let
// it show through, the way a real ink stamp validating a signature
// would, rather than covering it with a white rectangle. Embedded as a
// data URI, same pattern as logo.ts, so it needs no bundler asset
// config to work directly in an <img> tag.
export const HMZC_STAMP_DATA_URI =
  "data:image/png;base64,";
